def count_Num(n):
    """Write a python function to count numbers whose oth and nth bits are set.

    Count the numbers representable with ``n`` bits whose least
    significant (0th) bit and most significant (nth) bit are both set.

    With those two bits fixed to ``1``, each of the remaining
    ``n - 2`` bits may independently be ``0`` or ``1``, so the count
    is ``2 ** (n - 2)`` for ``n >= 2``. For ``n == 1`` the single bit
    is both the first and the last bit, giving one such number
    (``1``); for ``n == 0`` there are none.
    """
    if n < 0:
        raise ValueError("n must be non-negative")
    if n == 0:
        return 0
    if n == 1:
        return 1
    return 1 << (n - 2)
